local UserManager = {}

function UserManager:getName()
    return self.name
end

function UserManager:getEmail()
    return self.email
end

function UserManager:getAge()
    return self.age
end

function UserManager:getRole()
    return self.role
end

function UserManager:getScore()
    return self.score
end

function UserManager:getLevel()
    return self.level
end

function UserManager:getDepartment()
    return self.department
end

function UserManager:getActive()
    return self.active
end

function UserManager:getRegion()
    return self.region
end
